          <svg viewBox="0 0 24 24" width="16" height="16"><rect x="3.5" y="13" width="17" height="6.6" rx="3.3" fill="none" stroke="currentColor" stroke-width="1.6"/><circle cx="8" cy="16.3" r="1.05" fill="currentColor"/><circle cx="12" cy="16.3" r="1.05" fill="currentColor"/><circle cx="16" cy="16.3" r="1.05" fill="currentColor"/></svg>
