          <svg viewBox="0 0 24 24" width="16" height="16"><rect x="3.5" y="4.5" width="17" height="6.4" rx="3.2" fill="none" stroke="currentColor" stroke-width="1.6"/><rect x="3.5" y="13.1" width="17" height="6.4" rx="3.2" fill="none" stroke="currentColor" stroke-width="1.6"/><circle cx="8.2" cy="7.7" r="1.7" fill="currentColor"/><circle cx="15.8" cy="16.3" r="1.7" fill="currentColor"/></svg>
